import { useQueryClient } from "@tanstack/react-query"
import { Link, Outlet, useNavigate } from "@tanstack/react-router"
import { Menu as MenuIcon, Moon, Sun } from "lucide-react"
import { useState } from "react"
import type { ReactNode } from "react"
import { menu } from "@/menu.ts"
import { Button } from "@/components/ui/button.tsx"
import { cn } from "@/components/ui/cn.ts"
import { signOut, useSession } from "./auth.tsx"
import { t } from "./i18n.ts"
import { Toaster } from "./toast.tsx"

/** The theme: light, dark or the system's, kept in this browser. */
export function useTheme() {
  const [dark, setDark] = useState(() => document.documentElement.classList.contains("dark"))
  return {
    dark,
    toggle: () => {
      const next = !dark
      document.documentElement.classList.toggle("dark", next)
      try {
        localStorage.setItem("theme", next ? "dark" : "light")
      } catch {
        // Private windows may refuse storage: the theme lasts the visit.
      }
      setDark(next)
    },
  }
}

export function AppLayout({ brand, children }: { brand: string; children?: ReactNode }) {
  const [open, setOpen] = useState(false)
  const session = useSession()
  const theme = useTheme()
  const queryClient = useQueryClient()
  const navigate = useNavigate()
  return (
    <div className="flex min-h-screen bg-background text-foreground">
      <aside
        className={cn(
          "fixed inset-y-0 left-0 z-40 w-60 border-r border-border bg-card p-4 transition-transform md:static md:translate-x-0",
          open ? "translate-x-0" : "-translate-x-full",
        )}
      >
        <div className="mb-6 text-lg font-semibold">{brand}</div>
        <nav className="flex flex-col gap-1">
          {menu.map((item) => (
            <Link
              key={item.to}
              to={item.to as never}
              onClick={() => setOpen(false)}
              className="flex items-center gap-2 rounded-md px-3 py-2 text-sm hover:bg-muted"
              activeProps={{ className: "bg-muted font-medium" }}
            >
              {item.icon && <item.icon className="size-4" />}
              {item.label}
            </Link>
          ))}
        </nav>
      </aside>
      <div className="flex min-w-0 flex-1 flex-col">
        <header className="flex items-center gap-2 border-b border-border px-4 py-3">
          <Button variant="outline" className="md:hidden" onClick={() => setOpen(!open)} aria-label={t("menu")}>
            <MenuIcon className="size-4" />
          </Button>
          <div className="ml-auto flex items-center gap-2 text-sm">
            <Button variant="outline" onClick={theme.toggle} aria-label={t("theme")}>
              {theme.dark ? <Sun className="size-4" /> : <Moon className="size-4" />}
            </Button>
            {session && (
              <Button
                variant="outline"
                onClick={async () => {
                  await signOut(queryClient)
                  navigate({ to: "/login" })
                }}
              >
                {t("signOut")}
              </Button>
            )}
          </div>
        </header>
        <main className="flex-1 p-4 md:p-6">{children ?? <Outlet />}</main>
      </div>
      <Toaster />
    </div>
  )
}
